<?php require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';$date=$_GET['date']??date('Y-m-d');$stats=[];foreach(['sales'=>['sales','sale_date','total_amount'],'receiving'=>['stock_receivings','received_date','total_cost'],'usage'=>['stock_usages','usage_date','id'],'wastage'=>['wastages','wastage_date','cost_impact'],'transfers'=>['stock_transfers','transfer_date','id']] as $k=>[$t,$d,$v]){$q=$pdo->prepare("SELECT COUNT(*) records,COALESCE(SUM($v),0) value FROM $t WHERE $d=? AND deleted_at IS NULL");$q->execute([$date]);$stats[$k]=$q->fetch();}$activity=$pdo->prepare('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE DATE(a.created_at)=? ORDER BY a.id DESC LIMIT 30');$activity->execute([$date]);render_header('Daily Activity','activity');page_title('Daily Activity','TODAY AT A GLANCE','A complete timeline of operational and user activity.');?><form class="filters" style="margin-bottom:20px"><input type="date" name="date" value="<?=e($date)?>" data-auto-submit></form><div class="grid stats"><?php foreach($stats as $k=>$x):?><article class="stat"><div class="stat-head"><span><?=e(strtoupper($k))?></span></div><strong><?=number_format($x['records'])?></strong><span class="trend"><?=in_array($k,['sales','receiving','wastage'])?money($x['value']):number_format($x['value'])?> recorded</span></article><?php endforeach;?></div><article class="card"><div class="card-head"><div><h2>Activity timeline</h2><small>Immutable audit events</small></div></div><div class="activity-list"><?php foreach($activity as $x):?><div class="activity"><span class="activity-icon"><i data-icon="history"></i></span><div><b><?=e(ucfirst($x['action']).' · '.ucwords(str_replace('_',' ',$x['module'])))?></b><small><?=e($x['name']??'System')?> · <?=date('H:i:s',strtotime($x['created_at']))?></small></div><span class="status"><?=e($x['action'])?></span></div><?php endforeach;?><?php if(!$activity):?><div class="empty">No activity for this date.</div><?php endif;?></div></article><?php render_footer('activity');
